/**
 * @brief Classify each joint as continuous or bounded by inspecting the URDF directly.
 *
 * Most vendor URDFs (Kinova, Franka, KUKA) mark continuous joints with type="revolute" but
 * omit the `lower`/`upper` attributes from `<limit>`, rather than using type="continuous".
 * Pinocchio's in-memory model sometimes exposes these as 0/0 (not a huge sentinel), so we can't
 * rely on model.lowerPositionLimit/upperPositionLimit to detect them — we have to read the XML.
 *
 * Returns a vector sized to joint_names.size(); entry i is true iff that joint is continuous.
 */
inline std::vector<bool> deriveJointContinuityFromUrdf(const std::string& urdf_path,
                                                      const std::vector<std::string>& joint_names) {
    std::vector<bool> out(joint_names.size(), false);

    tinyxml2::XMLDocument doc;
    if (doc.LoadFile(urdf_path.c_str()) != tinyxml2::XML_SUCCESS) {
        RCLCPP_WARN(rclcpp::get_logger("RobotConfigLoader"),
            "deriveJointContinuityFromUrdf: could not load %s — defaulting all joints to bounded",
            urdf_path.c_str());
        return out;
    }

    auto* robot = doc.FirstChildElement("robot");
    if (!robot) return out;

    for (size_t i = 0; i < joint_names.size(); ++i) {
        for (auto* j = robot->FirstChildElement("joint"); j; j = j->NextSiblingElement("joint")) {
            const char* name = j->Attribute("name");
            if (!name || joint_names[i] != name) continue;

            const char* type = j->Attribute("type");
            if (type && std::string(type) == "continuous") {
                out[i] = true;
                break;
            }
            auto* lim = j->FirstChildElement("limit");
            // Continuous if <limit> missing entirely, or both lower/upper absent
            if (!lim || (!lim->Attribute("lower") && !lim->Attribute("upper"))) {
                out[i] = true;
            }
            break;
        }
    }
    return out;
}

/**
 * @brief Read per-joint position limits straight from the URDF XML (tinyxml2).
 *
 * Pinocchio-free counterpart of model.lowerPositionLimit/upperPositionLimit,
 * used in degraded mode (kinematics_solver: none / solver unavailable) so the
 * joint clamp limits fed to the controller stay correct without a solver.
 *
 * Joints whose <limit> omits lower/upper (continuous joints) get ±M_PI,
 * matching the continuous-joint fallback used with the solver present.
 *
 * @return false if the URDF could not be loaded (outputs left untouched).
 */
inline bool deriveJointLimitsFromUrdf(const std::string& urdf_path,
                                      const std::vector<std::string>& joint_names,
                                      std::vector<double>& lower,
                                      std::vector<double>& upper) {
    tinyxml2::XMLDocument doc;
    if (doc.LoadFile(urdf_path.c_str()) != tinyxml2::XML_SUCCESS) {
        RCLCPP_WARN(rclcpp::get_logger("RobotConfigLoader"),
            "deriveJointLimitsFromUrdf: could not load %s", urdf_path.c_str());
        return false;
    }
    auto* robot = doc.FirstChildElement("robot");
    if (!robot) return false;

    lower.assign(joint_names.size(), -M_PI);
    upper.assign(joint_names.size(),  M_PI);

    for (size_t i = 0; i < joint_names.size(); ++i) {
        for (auto* j = robot->FirstChildElement("joint"); j; j = j->NextSiblingElement("joint")) {
            const char* name = j->Attribute("name");
            if (!name || joint_names[i] != name) continue;

            if (auto* lim = j->FirstChildElement("limit")) {
                lim->QueryDoubleAttribute("lower", &lower[i]);
                lim->QueryDoubleAttribute("upper", &upper[i]);
            }
            break;
        }
    }
    return true;
}

/**
 * @brief Resolve full URDF path from config
 */
inline std::string resolveUrdfPath(const RobotConfig& config, const std::string& workspace_path = "") {
    std::string ws = workspace_path;
    if (ws.empty()) {
        ws = std::filesystem::current_path().string();
    }
    return ws + "/src/" + config.urdf_path;
}

/**
 * @brief Resolve full MuJoCo XML path from config
 */
inline std::string resolveMujocoPath(const RobotConfig& config, const std::string& workspace_path = "") {
    std::string ws = workspace_path;
    if (ws.empty()) {
        ws = std::filesystem::current_path().string();
    }
    return ws + "/src/" + config.mujoco_xml_path;
}

